package com.amit.jobagent.matching;import static org.assertj.core.api.Assertions.assertThat;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;
class WeightedScoringServiceTest{private final WeightedScoringService service=new WeightedScoringService();private MatchingConfigurationResponse config(){return new MatchingConfigurationResponse(UUID.randomUUID(),UUID.randomUUID(),35,20,15,15,10,5,85,75,60,1,25,100,500000,"v1",0,Instant.now(),Instant.now());}@Test void normalizesMissingDimensionWeight(){var r=service.calculate(new WeightedScoringService.Scores(100,100,100,100,100,null),config(),false,false,90);assertThat(r.score()).isEqualTo(100);assertThat(r.unassessedDimensions()).containsExactly("COMPENSATION");}@Test void usesDeterministicThresholdsAndHardFail(){var scores=new WeightedScoringService.Scores(85,85,85,85,85,85);assertThat(service.calculate(scores,config(),false,false,90).recommendation()).isEqualTo(Recommendation.STRONG_APPLY);assertThat(service.calculate(scores,config(),true,false,90).recommendation()).isEqualTo(Recommendation.SKIP);}@Test void lowConfidenceRequiresReview(){var scores=new WeightedScoringService.Scores(100,100,100,100,100,100);assertThat(service.calculate(scores,config(),false,false,49).recommendation()).isEqualTo(Recommendation.MANUAL_REVIEW);}}
